<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Icon from './patient-home-prototype/PrototypeIcon.vue'
import PrototypeDatePicker from './patient-home-prototype/PrototypeDatePicker.vue'
import './admin-home-prototype.css'
import './admin-resource-prototype.css'
import './patient-home-prototype/patient-home-prototype.css'

type ResourceKind = 'patients' | 'doctors' | 'departments'
type Action = 'enable' | 'disable' | 'lock' | 'unlock' | 'reset' | 'deactivate' | 'activate'
type Operation = { id: string; action: string; time: string; operator: string; note: string }
type Patient = { id: string; name: string; login: string; phone: string; source: string; registered: string; enabled: boolean; locked: boolean; lastLogin: string; operations: Operation[] }
type Doctor = { id: string; name: string; login: string; title: string; department: string; credentialStatus: 'PENDING' | 'CERTIFIED' | 'REJECTED'; enabled: boolean; locked: boolean; head: boolean; scheduleSummary: string; operations: Operation[] }
type Department = { id: string; name: string; description: string; active: boolean; headDoctor: string; doctorCount: number; scheduleCount: number; operations: Operation[] }
type AnyRecord = Patient | Doctor | Department
type NavItem = { label: string; icon: string; badge?: string }
type NavGroup = { name: string; items: NavItem[] }

const route = useRoute(), router = useRouter()
const groups: NavGroup[] = [
  { name: '运营', items: [{ label: '运营总览', icon: 'grid' }, { label: '预约与订单', icon: 'calendar' }, { label: '退款 / 异常', icon: 'warning', badge: '3' }] },
  { name: '资源', items: [{ label: '患者', icon: 'user' }, { label: '医生', icon: 'doctor' }, { label: '科室', icon: 'hospital' }, { label: '排班', icon: 'calendar' }, { label: '号源', icon: 'grid' }] },
  { name: '药品', items: [{ label: '药品与库存', icon: 'heart', badge: '4' }, { label: '药费订单', icon: 'wallet' }] },
  { name: '治理', items: [{ label: '审批与替诊', icon: 'file', badge: '6' }, { label: '新闻通知', icon: 'bell' }, { label: '审计日志', icon: 'scan' }] },
  { name: '系统', items: [{ label: '全局规则', icon: 'settings' }, { label: 'AI 配置', icon: 'sparkles' }, { label: '管理员账户', icon: 'user' }] },
]
const patients = ref<Patient[]>([
  { id: 'P-1007', name: '林知夏', login: 'lin.zhixia', phone: '13812345678', source: '患者注册', registered: '2026-08-14', enabled: true, locked: false, lastLogin: '今天 09:42', operations: [{ id: 'p1', action: '账户启用', time: '2026-08-14 10:12', operator: '系统', note: '完成患者注册' }] },
  { id: 'P-1021', name: '陈亦安', login: 'chen.yian', phone: '13987654321', source: '患者注册', registered: '2026-09-05', enabled: true, locked: false, lastLogin: '今天 08:16', operations: [{ id: 'p2', action: '账户启用', time: '2026-09-05 14:20', operator: '系统', note: '完成患者注册' }] },
  { id: 'P-1044', name: '沈嘉禾', login: 'shen.jiahe', phone: '13723456789', source: '管理员新增', registered: '2026-05-21', enabled: false, locked: false, lastLogin: '11月 10日 18:20', operations: [{ id: 'p3', action: '账户停用', time: '11月 10日 18:26', operator: '运营管理员', note: '用户主动申请停用' }] },
  { id: 'P-1098', name: '赵明远', login: 'zhao.mingyuan', phone: '13698761234', source: '患者注册', registered: '2026-10-03', enabled: true, locked: false, lastLogin: '11月 12日 21:08', operations: [{ id: 'p4', action: '账户启用', time: '2026-10-03 09:18', operator: '系统', note: '完成患者注册' }] },
])
const doctors = ref<Doctor[]>([
  { id: 'D-1021', name: '周宁', login: 'zhou.ning', title: '副主任医师', department: '内科', credentialStatus: 'CERTIFIED', enabled: true, locked: false, head: true, scheduleSummary: '今日 08:00–12:00 · 2 个排班', operations: [{ id: 'd1', action: '资质认证通过', time: '2026-06-02 15:30', operator: '运营管理员', note: '审核备注：材料完整' }] },
  { id: 'D-1098', name: '马凌', login: 'ma.ling', title: '主治医师', department: '内科', credentialStatus: 'PENDING', enabled: true, locked: true, head: false, scheduleSummary: '未来 7 日 · 3 个排班', operations: [{ id: 'd2', action: '提交资质审核', time: '11月 12日 10:10', operator: '马凌', note: '等待管理员审核' }] },
  { id: 'D-1106', name: '林牧', login: 'lin.mu', title: '住院医师', department: '全科医学科', credentialStatus: 'CERTIFIED', enabled: true, locked: false, head: false, scheduleSummary: '暂无近期排班', operations: [{ id: 'd3', action: '资质认证通过', time: '2026-07-18 09:00', operator: '运营管理员', note: '审核备注：材料完整' }] },
  { id: 'D-1138', name: '郭妤', login: 'guo.yu', title: '主任医师', department: '皮肤科', credentialStatus: 'REJECTED', enabled: false, locked: false, head: false, scheduleSummary: '暂无有效排班', operations: [{ id: 'd4', action: '资质审核未通过', time: '11月 08日 14:20', operator: '运营管理员', note: '审核备注：执业材料待补充' }] },
])
const departments = ref<Department[]>([
  { id: 'DEP-01', name: '内科', description: '覆盖常见内科疾病的线上问诊和线下面诊服务。', active: true, headDoctor: '周宁', doctorCount: 5, scheduleCount: 12, operations: [{ id: 'u1', action: '科室启用', time: '2026-01-03 09:00', operator: '院方管理员', note: '完成基础目录配置' }] },
  { id: 'DEP-02', name: '儿科', description: '提供儿童常见病和生长发育相关咨询。', active: true, headDoctor: '苏晚晴', doctorCount: 3, scheduleCount: 7, operations: [{ id: 'u2', action: '科室启用', time: '2026-01-03 09:00', operator: '院方管理员', note: '完成基础目录配置' }] },
  { id: 'DEP-03', name: '皮肤科', description: '提供皮肤常见病、过敏和慢性皮肤问题服务。', active: true, headDoctor: '姜悦', doctorCount: 2, scheduleCount: 5, operations: [{ id: 'u3', action: '科主任任命', time: '2026-07-18 11:20', operator: '运营管理员', note: '任命姜悦为科主任' }] },
  { id: 'DEP-04', name: '全科医学科', description: '提供常见健康问题的综合咨询和分诊服务。', active: false, headDoctor: '', doctorCount: 1, scheduleCount: 0, operations: [{ id: 'u4', action: '科室停用', time: '11月 01日 16:20', operator: '运营管理员', note: '后续新排班已暂停' }] },
])

const kind = computed<ResourceKind>(() => route.path.includes('admin-doctors') ? 'doctors' : route.path.includes('admin-departments') ? 'departments' : 'patients')
const pageTitle = computed(() => ({ patients: '患者资源工作台', doctors: '医生治理工作台', departments: '科室管理工作台' })[kind.value])
const pageDescription = computed(() => ({ patients: '查看患者资料与账户状态，患者预约通过入口跳转运营工作台。', doctors: '维护医生资质、科室归属和科主任标记，排班在独立页面处理。', departments: '维护科室主数据与负责人，查看医生和排班关联摘要。' })[kind.value])
const keyword = ref(typeof route.query.keyword === 'string' ? route.query.keyword : '')
const statusFilter = ref(typeof route.query.status === 'string' ? route.query.status : 'ALL')
const secondaryFilter = ref(typeof route.query.secondary === 'string' ? route.query.secondary : 'ALL')
const dateFilter = ref(typeof route.query.date === 'string' ? route.query.date : 'ALL')
const selected = ref<AnyRecord | null>(null)
const pendingAction = ref<{ item: AnyRecord; action: Action } | null>(null)
const newOpen = ref(false), reviewOpen = ref(false), departmentOpen = ref(false), headOpen = ref(false)
const notice = ref(''), collapsed = ref(false), mobileOpen = ref(false)
const reviewStatus = ref<Doctor['credentialStatus']>('PENDING'), reviewNote = ref('')
const departmentValue = ref(''), headDoctorValue = ref('')
const patientForm = reactive({ name: '', phone: '', login: '' })
const doctorForm = reactive({ name: '', login: '', title: '', department: '' })
const departmentForm = reactive({ name: '', description: '', active: true })
const credentialLabels: Record<Doctor['credentialStatus'], string> = { PENDING: '待审核', CERTIFIED: '已认证', REJECTED: '未通过' }
const departmentNames = computed(() => departments.value.map(item => item.name))

const rows = computed<AnyRecord[]>(() => {
  if (kind.value === 'patients') return patients.value.filter(item => {
    const query = keyword.value.trim().toLowerCase()
    return (!query || `${item.id}${item.name}${item.login}${item.phone}`.toLowerCase().includes(query)) && (statusFilter.value === 'ALL' || statusFilter.value === 'ENABLED' && item.enabled || statusFilter.value === 'DISABLED' && !item.enabled) && (dateFilter.value === 'ALL' || item.registered === dateFilter.value)
  })
  if (kind.value === 'doctors') return doctors.value.filter(item => {
    const query = keyword.value.trim().toLowerCase()
    return (!query || `${item.id}${item.name}${item.login}${item.title}${item.department}`.toLowerCase().includes(query)) && (statusFilter.value === 'ALL' || statusFilter.value === 'ENABLED' && item.enabled || statusFilter.value === 'DISABLED' && !item.enabled) && (secondaryFilter.value === 'ALL' || item.credentialStatus === secondaryFilter.value || secondaryFilter.value === 'HEAD' && item.head || secondaryFilter.value === item.department)
  })
  return departments.value.filter(item => {
    const query = keyword.value.trim().toLowerCase()
    return (!query || `${item.id}${item.name}${item.description}${item.headDoctor}`.toLowerCase().includes(query)) && (statusFilter.value === 'ALL' || statusFilter.value === 'ACTIVE' && item.active || statusFilter.value === 'INACTIVE' && !item.active) && (secondaryFilter.value === 'ALL' || secondaryFilter.value === 'HEAD' && Boolean(item.headDoctor) || secondaryFilter.value === 'NO_HEAD' && !item.headDoctor)
  })
})
const summary = computed(() => kind.value === 'patients' ? [{ label: '患者账户', value: patients.value.length, note: '统一患者资料目录' }, { label: '已启用', value: patients.value.filter(item => item.enabled).length, note: '可正常登录' }, { label: '已停用', value: patients.value.filter(item => !item.enabled).length, note: '历史记录保留' }, { label: '本月新增', value: 2, note: '按注册日期统计' }] : kind.value === 'doctors' ? [{ label: '医生总数', value: doctors.value.length, note: '包含全部资质状态' }, { label: '待审核', value: doctors.value.filter(item => item.credentialStatus === 'PENDING').length, note: '需要人工审核' }, { label: '已认证', value: doctors.value.filter(item => item.credentialStatus === 'CERTIFIED').length, note: '可参与排班' }, { label: '科主任', value: doctors.value.filter(item => item.head).length, note: '已任命负责人' }] : [{ label: '科室总数', value: departments.value.length, note: '医院专业分类' }, { label: '启用科室', value: departments.value.filter(item => item.active).length, note: '可接受新排班' }, { label: '科主任', value: departments.value.filter(item => item.headDoctor).length, note: '已配置负责人' }, { label: '未来排班', value: departments.value.reduce((sum, item) => sum + item.scheduleCount, 0), note: '关联排班摘要' }])

function syncUrl() { void router.replace({ query: { ...(keyword.value ? { keyword: keyword.value } : {}), ...(statusFilter.value !== 'ALL' ? { status: statusFilter.value } : {}), ...(secondaryFilter.value !== 'ALL' ? { secondary: secondaryFilter.value } : {}), ...(dateFilter.value !== 'ALL' ? { date: dateFilter.value } : {}) } }) }
function resetFilters() { keyword.value = ''; statusFilter.value = 'ALL'; secondaryFilter.value = 'ALL'; dateFilter.value = 'ALL'; syncUrl() }
function navigate(module: string) {
  mobileOpen.value = false
  if (module === '运营总览') return void router.push({ path: '/prototype/admin-home', query: { variant: 'A' } })
  if (module === '预约与订单' || module === '退款 / 异常') return void router.push({ path: '/prototype/admin-orders', query: { tab: module === '退款 / 异常' ? 'refunds' : 'appointments' } })
  if (module === '患者') return void router.push({ path: '/prototype/admin-patients' })
  if (module === '医生') return void router.push({ path: '/prototype/admin-doctors' })
  if (module === '科室') return void router.push({ path: '/prototype/admin-departments' })
  if (module === '排班') return void router.push({ path: '/prototype/admin-schedules' })
  void router.push({ path: '/prototype/admin-home', query: { module } })
}
function openDetails(item: AnyRecord) { selected.value = item; notice.value = '' }
function closeDetails() { selected.value = null; notice.value = '' }
function actionLabel(action: Action) { return ({ enable: '启用账户', disable: '停用账户', lock: '锁定登录', unlock: '解除登录锁定', reset: '重置登录状态', activate: '启用科室', deactivate: '停用科室' })[action] }
function actionImpact(action: Action) { return action === 'deactivate' ? '停用后禁止新排班和新预约，但会保留历史排班、预约和医疗记录。' : action === 'disable' ? '停用只影响账户登录，不会删除患者资料、预约或医疗记录。' : action === 'lock' ? '锁定只阻止登录，账户资料和既有业务记录继续保留。' : action === 'unlock' ? '解除登录锁定后，账户可以重新尝试登录。' : action === 'reset' ? '将清除当前登录状态，账户需要重新登录，不会修改密码或业务数据。' : '启用后恢复正常使用，既有业务记录继续保留。' }
function requestToggle(item: AnyRecord) {
  const action = kind.value === 'departments' ? ((item as Department).active ? 'deactivate' : 'activate') : ((item as Patient | Doctor).enabled ? 'disable' : 'enable')
  if (action === 'enable' || action === 'activate') { applyToggle(item, action); return }
  pendingAction.value = { item, action }
}
function applyToggle(item: AnyRecord, action: Action) {
  if (kind.value === 'departments') (item as Department).active = action === 'activate'
  else if (action === 'enable' || action === 'disable') (item as Patient | Doctor).enabled = action === 'enable'
  else if (action === 'lock' || action === 'unlock') (item as Patient | Doctor).locked = action === 'lock'
  item.operations.unshift({ id: `op-${Date.now()}`, action: actionLabel(action), time: '刚刚', operator: '运营管理员', note: actionImpact(action) }); notice.value = `${actionLabel(action)}已完成。`; pendingAction.value = null
}
function confirmToggle() { if (pendingAction.value) applyToggle(pendingAction.value.item, pendingAction.value.action) }
function requestAccountAction(item: Patient | Doctor, action: Exclude<Action, 'enable' | 'disable' | 'deactivate' | 'activate'>) { pendingAction.value = { item, action } }
function openNew() { newOpen.value = true; notice.value = '' }
function closeNew() { newOpen.value = false }
function submitNew() {
  if (kind.value === 'patients') {
    const item: Patient = { id: `P-${Date.now().toString().slice(-4)}`, name: patientForm.name, login: patientForm.login, phone: patientForm.phone, source: '管理员新增', registered: '2026-11-13', enabled: true, locked: false, lastLogin: '尚未登录', operations: [{ id: `op-${Date.now()}`, action: '账户启用', time: '刚刚', operator: '运营管理员', note: '管理员创建患者账户' }] }
    patients.value.unshift(item); selected.value = item; Object.assign(patientForm, { name: '', phone: '', login: '' }); notice.value = '患者账户已创建。'
  } else if (kind.value === 'doctors') {
    const item: Doctor = { id: `D-${Date.now().toString().slice(-4)}`, name: doctorForm.name, login: doctorForm.login, title: doctorForm.title, department: doctorForm.department, credentialStatus: 'PENDING', enabled: true, locked: false, head: false, scheduleSummary: '暂无排班', operations: [{ id: `op-${Date.now()}`, action: '提交资质审核', time: '刚刚', operator: '运营管理员', note: '新医生默认进入待审核状态' }] }
    doctors.value.unshift(item); selected.value = item; Object.assign(doctorForm, { name: '', login: '', title: '', department: '' }); notice.value = '医生账户已创建，资质状态为待审核。'
  } else {
    const item: Department = { id: `DEP-${Date.now().toString().slice(-4)}`, name: departmentForm.name, description: departmentForm.description, active: departmentForm.active, headDoctor: '', doctorCount: 0, scheduleCount: 0, operations: [{ id: `op-${Date.now()}`, action: departmentForm.active ? '科室启用' : '科室停用', time: '刚刚', operator: '运营管理员', note: '管理员创建科室主数据' }] }
    departments.value.unshift(item); selected.value = item; Object.assign(departmentForm, { name: '', description: '', active: true }); notice.value = '科室已创建。'
  }
  newOpen.value = false
}
function openReview() { const item = selected.value as Doctor; reviewStatus.value = item.credentialStatus; reviewNote.value = ''; reviewOpen.value = true }
function saveReview() { const item = selected.value as Doctor; if (!reviewNote.value.trim()) return; item.credentialStatus = reviewStatus.value; item.operations.unshift({ id: `op-${Date.now()}`, action: `资质${credentialLabels[reviewStatus.value]}`, time: '刚刚', operator: '运营管理员', note: `审核备注：${reviewNote.value.trim()}` }); reviewOpen.value = false; notice.value = '资质状态和审核备注已保存。' }
function openDepartmentEdit() { const item = selected.value as Doctor; departmentValue.value = item.department; departmentOpen.value = true }
function saveDepartmentEdit() { const item = selected.value as Doctor; item.department = departmentValue.value; item.operations.unshift({ id: `op-${Date.now()}`, action: '调整科室归属', time: '刚刚', operator: '运营管理员', note: `调整为${departmentValue.value}` }); departmentOpen.value = false; notice.value = '医生科室归属已更新。' }
function toggleHead(item: Doctor) {
  const department = departments.value.find(value => value.name === item.department)
  const previous = doctors.value.find(value => value.department === item.department && value.head && value.id !== item.id)
  if (item.head) {
    item.head = false
    if (department?.headDoctor === item.name) department.headDoctor = ''
    item.operations.unshift({ id: `op-${Date.now()}`, action: '取消科主任标记', time: '刚刚', operator: '运营管理员', note: '科主任标记已更新' })
    notice.value = '已取消科主任标记。'
    return
  }
  doctors.value.forEach(value => { if (value.department === item.department) value.head = value.id === item.id })
  if (department) department.headDoctor = item.name
  item.operations.unshift({ id: `op-${Date.now()}`, action: '标记科主任', time: '刚刚', operator: '运营管理员', note: previous ? `已替换${previous.name}的科主任标记` : '科主任标记已更新' })
  notice.value = previous ? `已由${previous.name}更换为${item.name}担任科主任。` : '已标记为科主任。'
}
function openHead() { const item = selected.value as Department; headDoctorValue.value = doctors.value.find(doctor => doctor.name === item.headDoctor)?.id ?? ''; headOpen.value = true }
function saveHead() { const item = selected.value as Department; const doctor = doctors.value.find(value => value.id === headDoctorValue.value); doctors.value.forEach(value => { if (value.department === item.name) value.head = value.id === headDoctorValue.value }); item.headDoctor = doctor?.name ?? ''; item.operations.unshift({ id: `op-${Date.now()}`, action: doctor ? '科主任任命' : '科主任解除', time: '刚刚', operator: '运营管理员', note: doctor ? `任命${doctor.name}为科主任` : '解除科主任任命' }); headOpen.value = false; notice.value = doctor ? `已任命${doctor.name}为科主任。` : '已解除科主任任命。' }
function onKeydown(event: KeyboardEvent) { if (event.key === 'Escape') { pendingAction.value = null; newOpen.value = false; reviewOpen.value = false; departmentOpen.value = false; headOpen.value = false; closeDetails() } }
watch([keyword, statusFilter, secondaryFilter, dateFilter], syncUrl)
onMounted(() => window.addEventListener('keydown', onKeydown))
onBeforeUnmount(() => window.removeEventListener('keydown', onKeydown))
</script>

<template>
  <div class="admin-prototype" :class="{ 'admin-collapsed': collapsed }">
    <aside class="admin-sidebar" :class="{ 'admin-mobile-open': mobileOpen }" aria-label="管理员端导航"><div class="admin-profile"><span class="admin-avatar">管</span><div class="admin-profile-copy"><strong>运营管理员</strong><span>平台治理与运营</span><em>管理员</em></div></div><nav class="admin-nav" aria-label="管理员功能导航"><template v-for="group in groups" :key="group.name"><p class="admin-nav-caption">{{ group.name }}</p><button v-for="item in group.items" :key="item.label" type="button" :class="{ active: (kind === 'patients' && item.label === '患者') || (kind === 'doctors' && item.label === '医生') || (kind === 'departments' && item.label === '科室') }" :aria-label="item.label" @click="navigate(item.label)"><Icon :name="item.icon" /><span>{{ item.label }}</span><b v-if="item.badge">{{ item.badge }}</b></button></template></nav><div class="admin-sidebar-bottom"><div class="admin-permission"><Icon name="lock" /><div><strong>医疗内容权限</strong><span>默认未开启</span></div></div><button type="button" class="admin-collapse" :aria-label="collapsed ? '展开侧栏' : '收起侧栏'" :aria-expanded="!collapsed" @click="collapsed = !collapsed"><Icon name="chevron" /><span>{{ collapsed ? '展开侧栏' : '收起侧栏' }}</span></button></div></aside>
    <button v-if="mobileOpen" type="button" class="admin-backdrop" aria-label="关闭侧栏" @click="mobileOpen = false"></button>
    <section class="admin-workspace"><header class="admin-topbar"><div class="admin-topbar-left"><button type="button" class="admin-mobile-toggle" aria-label="打开侧栏" @click="mobileOpen = true"><Icon name="menu" /></button><div class="admin-brand"><span><Icon name="hospital" /></span><div><strong>智能医疗问诊预约系统</strong><small>ADMIN OPERATIONS</small></div></div><div class="admin-hospital"><i></i>市一医院 · 管理员工作台</div></div><div class="admin-topbar-right"><div class="admin-updated"><span>实时演示数据</span><Icon name="refresh" /></div><button type="button" class="admin-bell" aria-label="查看通知"><Icon name="bell" /><i></i></button><div class="admin-user"><span>管</span><strong>运营管理员</strong><Icon name="chevron" /></div></div></header>
      <main class="admin-content resource-content"><div class="resource-heading"><div><span class="admin-eyebrow">资源 / {{ kind === 'patients' ? '患者' : kind === 'doctors' ? '医生' : '科室' }}</span><h1>{{ pageTitle }}</h1><p>{{ pageDescription }}</p></div><div class="resource-heading-actions"><span class="resource-demo-chip"><i></i>虚构演示数据</span><button type="button" class="resource-add-button" @click="openNew"><Icon name="cross" />新增{{ kind === 'patients' ? '患者' : kind === 'doctors' ? '医生' : '科室' }}</button></div></div>
        <section class="resource-summary" aria-label="资源摘要"><article v-for="item in summary" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></article></section>
        <section class="resource-panel" :aria-label="`${pageTitle}列表`"><div class="resource-panel-heading"><div><h2>{{ kind === 'patients' ? '患者资料目录' : kind === 'doctors' ? '医生治理目录' : '科室主数据目录' }} <span>{{ rows.length }} 条</span></h2><p>{{ kind === 'patients' ? '患者资料与账户状态分开表达' : kind === 'doctors' ? '资质、归属和科主任标记独立展示' : '主数据、负责人和关联摘要独立展示' }}</p></div><button type="button" class="admin-soft resource-reset" @click="resetFilters"><Icon name="refresh" />重置筛选</button></div>
          <div class="resource-filters"><label class="resource-search"><span>关键词</span><div><Icon name="search" /><input v-model="keyword" aria-label="搜索资源" :placeholder="kind === 'patients' ? '姓名、账号或手机号' : kind === 'doctors' ? '姓名、账号或科室' : '科室名称或负责人'"></div></label><label><span>{{ kind === 'doctors' ? '账户状态' : kind === 'departments' ? '科室状态' : '账户状态' }}</span><select v-model="statusFilter" aria-label="资源状态"><option value="ALL">全部状态</option><option v-if="kind === 'departments'" value="ACTIVE">已启用</option><option v-if="kind === 'departments'" value="INACTIVE">已停用</option><option v-if="kind !== 'departments'" value="ENABLED">已启用</option><option v-if="kind !== 'departments'" value="DISABLED">已停用</option></select></label><label v-if="kind === 'doctors'"><span>资质 / 标记</span><select v-model="secondaryFilter" aria-label="医生资质筛选"><option value="ALL">全部资质</option><option value="PENDING">待审核</option><option value="CERTIFIED">已认证</option><option value="REJECTED">未通过</option><option value="HEAD">科主任</option></select></label><label v-if="kind === 'departments'"><span>负责人</span><select v-model="secondaryFilter" aria-label="科室负责人筛选"><option value="ALL">全部科室</option><option value="HEAD">已配置负责人</option><option value="NO_HEAD">待任命负责人</option></select></label><PrototypeDatePicker v-if="kind === 'patients'" v-model="dateFilter" label="注册日期" min-date="2026-05-01" max-date="2026-11-13" allow-all @update:model-value="syncUrl" /></div>
          <div class="resource-table-wrap"><table class="resource-table"><thead><tr v-if="kind === 'patients'"><th>患者</th><th>联系方式</th><th>注册来源</th><th>账户状态</th><th>注册时间</th><th>操作</th></tr><tr v-else-if="kind === 'doctors'"><th>医生</th><th>职称 / 科室</th><th>资质状态</th><th>科主任</th><th>排班摘要</th><th>账户</th><th>操作</th></tr><tr v-else><th>科室</th><th>负责人</th><th>状态</th><th>医生数量</th><th>未来排班</th><th>服务说明</th><th>操作</th></tr></thead><tbody>
            <template v-if="kind === 'patients'"><tr v-for="item in rows as Patient[]" :key="item.id"><td><div class="resource-person"><span>{{ item.name.slice(0, 1) }}</span><div><strong>{{ item.name }}</strong><small>{{ item.login }} · {{ item.id }}</small></div></div></td><td><span class="resource-muted">{{ item.phone.slice(0, 3) }} **** {{ item.phone.slice(-4) }}</span></td><td><span class="resource-muted">{{ item.source }}</span></td><td><span :class="['resource-status', item.enabled ? 'enabled' : 'disabled']"><i></i>{{ item.enabled ? '已启用' : '已停用' }}</span></td><td><span class="resource-muted">{{ item.registered }}</span></td><td><button type="button" class="resource-row-action" :aria-label="`查看${item.id}详情`" @click="openDetails(item)">查看详情 <Icon name="chevron" /></button></td></tr></template>
            <template v-else-if="kind === 'doctors'"><tr v-for="item in rows as Doctor[]" :key="item.id"><td><div class="resource-person"><span class="doctor-avatar">{{ item.name.slice(0, 1) }}</span><div><strong>{{ item.name }}</strong><small>{{ item.login }} · {{ item.id }}</small></div></div></td><td><strong class="resource-cell-strong">{{ item.title }}</strong><small class="resource-muted">{{ item.department }}</small></td><td><span :class="['credential-badge', `credential-${item.credentialStatus.toLowerCase()}`]">{{ credentialLabels[item.credentialStatus] }}</span></td><td><span v-if="item.head" class="head-badge">科主任</span><span v-else class="resource-muted">—</span></td><td><span class="resource-muted">{{ item.scheduleSummary }}</span></td><td><span :class="['resource-status', item.enabled ? 'enabled' : 'disabled']"><i></i>{{ item.enabled ? '已启用' : '已停用' }}</span></td><td><button type="button" class="resource-row-action" :aria-label="`查看${item.id}详情`" @click="openDetails(item)">查看详情 <Icon name="chevron" /></button></td></tr></template>
            <template v-else><tr v-for="item in rows as Department[]" :key="item.id"><td><div class="resource-person"><span class="department-avatar"><Icon name="hospital" /></span><div><strong>{{ item.name }}</strong><small>{{ item.id }}</small></div></div></td><td><span v-if="item.headDoctor" class="head-badge">{{ item.headDoctor }}</span><span v-else class="resource-muted">待任命</span></td><td><span :class="['resource-status', item.active ? 'enabled' : 'disabled']"><i></i>{{ item.active ? '已启用' : '已停用' }}</span></td><td><strong class="resource-cell-strong">{{ item.doctorCount }} 位</strong></td><td><strong class="resource-cell-strong">{{ item.scheduleCount }} 个</strong></td><td><span class="resource-muted resource-description">{{ item.description }}</span></td><td><button type="button" class="resource-row-action" :aria-label="`查看${item.id}详情`" @click="openDetails(item)">查看详情 <Icon name="chevron" /></button></td></tr></template>
            <tr v-if="!rows.length"><td :colspan="kind === 'doctors' ? 7 : 6" class="resource-empty"><Icon name="search" /><strong>没有匹配的资源</strong><span>可以清除筛选后查看全部演示数据。</span></td></tr>
          </tbody></table></div>
        </section><p class="resource-footnote"><Icon name="shield" /> {{ kind === 'patients' ? '患者页不展示医疗内容；预约通过入口跳转预约运营工作台。' : kind === 'doctors' ? '资质审核保留备注和时间；排班明细在独立排班页面维护。' : '科室停用不会删除历史记录，停用后禁止新排班和新预约。' }}</p>
      </main>
    </section>

    <div v-if="selected" class="resource-drawer-backdrop" @click="closeDetails"><aside class="resource-drawer" aria-label="资源详情" @click.stop><button type="button" class="resource-drawer-close" aria-label="关闭资源详情" @click="closeDetails"><Icon name="close" /></button>
      <template v-if="kind === 'patients'"><span class="resource-drawer-kicker">患者资料 · {{ (selected as Patient).enabled ? '已启用' : '已停用' }}</span><div class="resource-drawer-person"><span>{{ (selected as Patient).name.slice(0, 1) }}</span><div><h2>{{ (selected as Patient).name }}</h2><p>{{ (selected as Patient).login }} · {{ (selected as Patient).id }}</p></div></div><div class="resource-detail-grid"><span>手机号<strong>{{ (selected as Patient).phone.slice(0, 3) }} **** {{ (selected as Patient).phone.slice(-4) }}</strong></span><span>注册来源<strong>{{ (selected as Patient).source }}</strong></span><span>注册时间<strong>{{ (selected as Patient).registered }}</strong></span><span>最近登录<strong>{{ (selected as Patient).lastLogin }}</strong></span><span>登录状态<strong>{{ (selected as Patient).locked ? '已锁定' : '正常' }}</strong></span></div><p v-if="notice" class="resource-feedback" role="status">{{ notice }}</p><div class="resource-drawer-actions"><button type="button" class="resource-soft" @click="router.push({ path: '/prototype/admin-orders', query: { tab: 'appointments', keyword: (selected as Patient).name } })">查看预约与订单</button><button type="button" class="resource-soft" @click="requestAccountAction(selected as Patient, (selected as Patient).locked ? 'unlock' : 'lock')">{{ (selected as Patient).locked ? '解除登录锁定' : '锁定登录' }}</button><button type="button" class="resource-soft" @click="requestAccountAction(selected as Patient, 'reset')">重置登录状态</button><button type="button" :class="(selected as Patient).enabled ? 'resource-danger' : 'resource-primary'" @click="requestToggle(selected)">{{ (selected as Patient).enabled ? '停用账户' : '启用账户' }}</button></div></template>
      <template v-else-if="kind === 'doctors'"><span class="resource-drawer-kicker">医生治理 · {{ credentialLabels[(selected as Doctor).credentialStatus] }}</span><div class="resource-drawer-person"><span class="doctor-avatar">{{ (selected as Doctor).name.slice(0, 1) }}</span><div><h2>{{ (selected as Doctor).name }}</h2><p>{{ (selected as Doctor).login }} · {{ (selected as Doctor).id }}</p></div></div><div class="resource-detail-grid"><span>职称<strong>{{ (selected as Doctor).title }}</strong></span><span>所属科室<strong>{{ (selected as Doctor).department }}</strong></span><span>资质状态<strong>{{ credentialLabels[(selected as Doctor).credentialStatus] }}</strong></span><span>科主任<strong>{{ (selected as Doctor).head ? '已标记' : '未标记' }}</strong></span><span>排班摘要<strong>{{ (selected as Doctor).scheduleSummary }}</strong></span><span>账户状态<strong>{{ (selected as Doctor).enabled ? '已启用' : '已停用' }}</strong></span><span>登录状态<strong>{{ (selected as Doctor).locked ? '已锁定' : '正常' }}</strong></span></div><p v-if="notice" class="resource-feedback" role="status">{{ notice }}</p><div class="resource-drawer-actions"><button type="button" class="resource-soft" @click="openReview">审核资质</button><button type="button" class="resource-soft" @click="openDepartmentEdit">调整科室</button><button type="button" class="resource-outline" @click="toggleHead(selected as Doctor)">{{ (selected as Doctor).head ? '取消科主任标记' : '标记科主任' }}</button><button type="button" class="resource-soft" @click="router.push({ path: '/prototype/admin-home', query: { module: '排班' } })">查看排班</button><button type="button" class="resource-soft" @click="requestAccountAction(selected as Doctor, (selected as Doctor).locked ? 'unlock' : 'lock')">{{ (selected as Doctor).locked ? '解除登录锁定' : '锁定登录' }}</button><button type="button" class="resource-soft" @click="requestAccountAction(selected as Doctor, 'reset')">重置登录状态</button><button type="button" :class="(selected as Doctor).enabled ? 'resource-danger' : 'resource-primary'" @click="requestToggle(selected)">{{ (selected as Doctor).enabled ? '停用账户' : '启用账户' }}</button></div></template>
      <template v-else><span class="resource-drawer-kicker">科室主数据 · {{ (selected as Department).active ? '已启用' : '已停用' }}</span><div class="resource-drawer-person"><span class="department-avatar"><Icon name="hospital" /></span><div><h2>{{ (selected as Department).name }}</h2><p>{{ (selected as Department).id }}</p></div></div><div class="resource-detail-grid"><span>科主任<strong>{{ (selected as Department).headDoctor || '待任命' }}</strong></span><span>医生数量<strong>{{ (selected as Department).doctorCount }} 位</strong></span><span>未来排班<strong>{{ (selected as Department).scheduleCount }} 个</strong></span><span>服务状态<strong>{{ (selected as Department).active ? '可接受新排班' : '已暂停新增' }}</strong></span></div><p class="resource-description-block">{{ (selected as Department).description }}</p><p v-if="notice" class="resource-feedback" role="status">{{ notice }}</p><div class="resource-drawer-actions"><button type="button" class="resource-soft" @click="openHead">任命 / 更换科主任</button><button type="button" class="resource-soft" @click="router.push({ path: '/prototype/admin-doctors', query: { secondary: 'ALL', keyword: (selected as Department).name } })">查看所属医生</button><button type="button" :class="(selected as Department).active ? 'resource-danger' : 'resource-primary'" @click="requestToggle(selected)">{{ (selected as Department).active ? '停用科室' : '启用科室' }}</button></div></template>
      <div class="resource-operations"><h3>最近治理记录</h3><div v-for="operation in selected.operations.slice(0, 3)" :key="operation.id" class="resource-operation"><i></i><div><strong>{{ operation.action }}</strong><span>{{ operation.time }} · {{ operation.operator }}</span><small>{{ operation.note }}</small></div></div></div><p class="resource-drawer-note">账户启停只影响登录；资质、科室关系、科主任和历史业务记录分别保留。</p>
    </aside></div>

    <div v-if="pendingAction" class="resource-modal-backdrop"><section class="resource-confirm" role="dialog" aria-modal="true" :aria-label="`确认${actionLabel(pendingAction.action)}`"><span class="resource-confirm-icon"><Icon name="warning" /></span><h2>确认{{ actionLabel(pendingAction.action) }}</h2><p>{{ kind === 'departments' ? (pendingAction.item as Department).name : (pendingAction.item as Patient | Doctor).name }}</p><div class="resource-confirm-impact">{{ actionImpact(pendingAction.action) }}</div><div class="resource-confirm-actions"><button type="button" class="resource-soft" @click="pendingAction = null">取消</button><button type="button" class="resource-primary" @click="confirmToggle">确认{{ actionLabel(pendingAction.action) }}</button></div></section></div>
    <div v-if="newOpen" class="resource-modal-backdrop"><section class="resource-form-modal" role="dialog" aria-modal="true" :aria-label="`新增${kind === 'patients' ? '患者' : kind === 'doctors' ? '医生' : '科室'}`"><button type="button" class="resource-modal-close" aria-label="关闭新增表单" @click="closeNew"><Icon name="close" /></button><span class="resource-drawer-kicker">资源新增</span><h2>新增{{ kind === 'patients' ? '患者' : kind === 'doctors' ? '医生' : '科室' }}</h2><form v-if="kind === 'patients'" @submit.prevent="submitNew"><label>姓名<input v-model="patientForm.name" required maxlength="40"></label><label>手机号<input v-model="patientForm.phone" required maxlength="20"></label><label>登录账号<input v-model="patientForm.login" required maxlength="60"></label><p class="resource-form-note">新患者账户创建后默认启用。</p><button type="submit" class="resource-add-button">创建患者账户</button></form><form v-else-if="kind === 'doctors'" @submit.prevent="submitNew"><label>姓名<input v-model="doctorForm.name" required maxlength="40"></label><label>登录账号<input v-model="doctorForm.login" required maxlength="60"></label><label>职称<input v-model="doctorForm.title" required maxlength="60"></label><label>所属科室<select v-model="doctorForm.department" required><option value="" disabled>请选择科室</option><option v-for="item in departmentNames" :key="item">{{ item }}</option></select></label><p class="resource-form-note">新医生资质默认待审核，不能直接发布排班。</p><button type="submit" class="resource-add-button">创建医生账户</button></form><form v-else @submit.prevent="submitNew"><label>科室名称<input v-model="departmentForm.name" required maxlength="60"></label><label>服务说明<textarea v-model="departmentForm.description" required maxlength="500"></textarea></label><label class="resource-check"><input v-model="departmentForm.active" type="checkbox">创建后启用科室</label><button type="submit" class="resource-add-button">创建科室</button></form></section></div>
    <div v-if="reviewOpen" class="resource-modal-backdrop"><section class="resource-form-modal" role="dialog" aria-modal="true" aria-label="审核医生资质"><button type="button" class="resource-modal-close" aria-label="关闭资质审核" @click="reviewOpen = false"><Icon name="close" /></button><span class="resource-drawer-kicker">医生治理 · 资质审核</span><h2>审核资质</h2><label>审核结果<select v-model="reviewStatus"><option value="PENDING">待审核</option><option value="CERTIFIED">已认证</option><option value="REJECTED">未通过</option></select></label><label>审核备注<textarea v-model="reviewNote" required maxlength="300" placeholder="请填写审核依据或补充材料说明"></textarea></label><button type="button" class="resource-primary" @click="saveReview">保存审核结果</button></section></div>
    <div v-if="departmentOpen" class="resource-modal-backdrop"><section class="resource-form-modal" role="dialog" aria-modal="true" aria-label="调整医生科室"><button type="button" class="resource-modal-close" aria-label="关闭科室调整" @click="departmentOpen = false"><Icon name="close" /></button><span class="resource-drawer-kicker">医生治理 · 科室归属</span><h2>调整科室</h2><label>所属科室<select v-model="departmentValue"><option v-for="item in departmentNames.filter(value => departments.find(department => department.name === value)?.active)" :key="item">{{ item }}</option></select></label><button type="button" class="resource-primary" @click="saveDepartmentEdit">保存科室归属</button></section></div>
    <div v-if="headOpen" class="resource-modal-backdrop"><section class="resource-form-modal" role="dialog" aria-modal="true" aria-label="任命科主任"><button type="button" class="resource-modal-close" aria-label="关闭科主任任命" @click="headOpen = false"><Icon name="close" /></button><span class="resource-drawer-kicker">科室治理 · 负责人</span><h2>任命 / 更换科主任</h2><label>本科室已认证医生<select v-model="headDoctorValue"><option value="">暂不设置</option><option v-for="item in doctors.filter(doctor => doctor.department === (selected as Department).name && doctor.credentialStatus === 'CERTIFIED' && doctor.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.title }}</option></select></label><p class="resource-form-note">只有本部门已认证且启用的医生可以担任科主任。</p><button type="button" class="resource-primary" @click="saveHead">保存负责人</button></section></div>
  </div>
</template>
